package com.italiano2774.nativeapp;
import android.os.Bundle;import android.view.*;import android.widget.*;import androidx.annotation.*;import androidx.core.content.ContextCompat;import androidx.fragment.app.Fragment;import java.time.LocalDate;import java.util.*;
public class CoreSentenceFragment extends Fragment{
 @Nullable @Override public View onCreateView(@NonNull LayoutInflater i,@Nullable ViewGroup c,@Nullable Bundle s){View v=i.inflate(R.layout.fragment_core_sentences,c,false);ProgressStore p=new ProgressStore(requireContext());List<CoreSentence> all=CoreSentenceRepository.get(requireContext()).all();((TextView)v.findViewById(R.id.text_cs_summary)).setText("共 "+all.size()+" 句 · 句子FSRS历史正确率 "+p.auxiliaryAccuracy("sentence_fsrs")+"% · 主动回忆 "+p.auxiliaryAccuracy("active_recall")+"%");v.findViewById(R.id.button_cs_300).setOnClickListener(x->((MainActivity)requireActivity()).openActiveRecall(300));v.findViewById(R.id.button_cs_430).setOnClickListener(x->((MainActivity)requireActivity()).openActiveRecall(430));v.findViewById(R.id.button_cs_due).setOnClickListener(x->((MainActivity)requireActivity()).openSentenceReview());LinearLayout box=v.findViewById(R.id.container_cs_examples);List<CoreSentence> sample=new ArrayList<>(all.subList(0,Math.min(30,all.size())));Collections.shuffle(sample);for(CoreSentence cs:sample.subList(0,Math.min(8,sample.size()))){LinearLayout card=new LinearLayout(requireContext());card.setOrientation(LinearLayout.VERTICAL);card.setPadding(dp(14),dp(12),dp(14),dp(12));card.setBackgroundResource(R.drawable.bg_soft_panel);LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT);cp.topMargin=dp(7);box.addView(card,cp);TextView a=new TextView(requireContext());a.setText(cs.italian);a.setTextColor(ContextCompat.getColor(requireContext(),R.color.text_primary));a.setTextSize(16);a.setTypeface(android.graphics.Typeface.DEFAULT,android.graphics.Typeface.BOLD);card.addView(a);TextView b=new TextView(requireContext());b.setText(cs.chinese+" · "+cs.level+" · "+cs.category);b.setTextColor(ContextCompat.getColor(requireContext(),R.color.text_secondary));b.setTextSize(11);LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT);bp.topMargin=dp(4);card.addView(b,bp);}return v;}
 private int dp(int x){return (int)(x*getResources().getDisplayMetrics().density+.5f);}
}
